                break

            try:
                if hasattr(df, "SetFuzzyValue"):
                    df.SetFuzzyValue(1e-4)
                if hasattr(df, "SetUseOBB"):
                    df.SetUseOBB(True)
            except Exception:
                pass

            df.Build()
            if hasattr(df, "IsDone") and not df.IsDone():
                print("  Defeaturing IsDone()=False; aborting removal.")
                break

            new_shape = cq.Shape.cast(df.Shape())

            # Fix shape after defeaturing
            try:
                fixer = ShapeFix_Shape(new_shape.wrapped)
                fixer.Perform()
                new_shape = cq.Shape.cast(fixer.Shape())
            except Exception as e:
                print("  ShapeFix failed (continuing):", e)

            current = new_shape
            c10, t10 = count_r_faces(current, R_OLD)
            print(
                f"  After pass {p+1}: valid={current.isValid()} faces={len(current.Faces())} edges={len(current.Edges())}  "
                f"remaining R~{R_OLD}: cyl={c10}, tor(minor)={t10}"
            )
            if c10 == 0 and t10 == 0:
                break

        except Exception as e:
            print("Defeaturing exception:", e)
            break

    c10, t10 = count_r_faces(current, R_OLD)
    if c10 != 0 or t10 != 0:
        print(
            f"WARNING: R~{R_OLD} surfaces still present after defeaturing (cyl={c10}, tor={t10}). "
            f"Returning without adding new fillet to avoid stacking."
        )
        return current

    # -----------------------
    # 2) Add uniform R2 fillet to the same outer perimeter edge loops
    #    Robust selection: find the two largest planar (annular) faces, and fillet
    #    the edges of their OUTER wires (not the inner opening).
    # -----------------------
    from math import sqrt

    def dot(a, b):
        return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]

    def sub(a, b):
        return (a[0]-b[0], a[1]-b[1], a[2]-b[2])

    def norm(v):
        return sqrt(dot(v, v))

    def unit(v):
        n = norm(v)
        if n < 1e-12:
            return (0.0, 0.0, 0.0)
        return (v[0]/n, v[1]/n, v[2]/n)

    planar = []
    for f in current.Faces():
        ad = BRepAdaptor_Surface(f.wrapped, True)
        if ad.GetType() != GeomAbs_Plane:
            continue
        try:
            area = float(cq.Face(f.wrapped).Area())
        except Exception:
            area = 0.0
        pln = ad.Plane()
        n = pln.Axis().Direction()
        p0 = pln.Location()
        nvec = unit((float(n.X()), float(n.Y()), float(n.Z())))
        pvec = (float(p0.X()), float(p0.Y()), float(p0.Z()))
        planar.append((area, f, nvec, pvec))

    planar.sort(key=lambda x: x[0], reverse=True)
    print(f"Planar faces found: {len(planar)}")
    for i, (a, _f, nvec, pvec) in enumerate(planar[:6]):
        print(f"  planar[{i}] area={a:.3f} n={tuple(round(v,4) for v in nvec)} p={tuple(round(v,3) for v in pvec)}")

    # Find best opposing (or parallel) pair among the largest planar faces
    best = None
    topN = min(12, len(planar))
    for i in range(topN):
        ai, fi, ni, pi = planar[i]
        for j in range(i+1, topN):
            aj, fj, nj, pj = planar[j]
            if abs(dot(ni, nj)) < 0.985:
                continue
            # plane separation along ni
            d = abs(dot(sub(pj, pi), ni))
            score = d * (ai + aj)
            if best is None or score > best[0]:
                best = (score, d, (ai, fi, ni, pi), (aj, fj, nj, pj))

    if best is None:
        print("ERROR: Could not identify the two broad planar faces for outer-edge selection. Returning current.")
        return current

    _score, dsep, A, B = best
    (ai, faceA, nA, pA) = A
    (aj, faceB, nB, pB) = B
    print(f"Selected planar face pair: areas=({ai:.3f},{aj:.3f}) separation~{dsep:.3f}")

    # Collect outer-wire edges from both faces
    edges = []
    for lab, f in [("A", faceA), ("B", faceB)]:
        try:
            cf = cq.Face(f.wrapped)
            ow = cf.outerWire()
            ews = ow.Edges()
            print(f"  Face {lab}: outerWire edges={len(ews)}")
            for e in ews:
                edges.append(e.wrapped)
        except Exception as e:
            print(f"  Failed extracting outerWire for face {lab}:", e)

    # Deduplicate edges by HashCode
    dedup = {}
    uniq = []
    for ew in edges:
        try:
            hk = int(ew.HashCode(10**9))
        except Exception:
            hk = id(ew)
        if hk in dedup:
            continue
        dedup[hk] = True
        uniq.append(ew)
    edges = uniq

    print(f"Edges selected for new R{R_NEW} fillet (from outer wires): {len(edges)}")
    if len(edges) == 0:
        print("No edges selected; returning current for inspection.")
        return current

    # Apply fillet
    try:
        from OCP.BRepFilletAPI import BRepFilletAPI_MakeFillet
        from OCP.ShapeFix import ShapeFix_Shape

        mk = BRepFilletAPI_MakeFillet(current.wrapped)
        for ew in edges:
            mk.Add(R_NEW, ew)
        mk.Build()
        if hasattr(mk, "IsDone") and not mk.IsDone():
            print("Fillet tool IsDone()=False; returning current.")
            return current

        result = cq.Shape.cast(mk.Shape())

        try:
            fixer = ShapeFix_Shape(result.wrapped)
            fixer.Perform()
            result = cq.Shape.cast(fixer.Shape())
        except Exception:
            pass

        print("Applied new fillet")
        print(f"  result valid={result.isValid()} faces={len(result.Faces())} edges={len(result.Edges())}")

        c10, t10 = count_r_faces(result, R_OLD)
        c2, t2 = count_r_faces(result, R_NEW)
        print(f"Post-check: remaining R~{R_OLD}: cyl={c10}, tor(minor)={t10}")
        print(f"Post-check: detected R~{R_NEW}: cyl={c2}, tor(minor)={t2}")

        return result

    except Exception as e:
        print("Fillet exception:", e)
        return current
